BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('4ef2aa82-be0a-50e4-9f82-e52bb5f1bd14', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Objeto polimórfico que oferece comportamento adequado à ausência de um valor, evitando verificações de null espalhadas.”?', '["Método abstract","Método protected","Método final","Fixação da especialização na instanciação","Null Object"]'::jsonb, 4, 'Null Object: objeto polimórfico que oferece comportamento adequado à ausência de um valor, evitando verificações de null espalhadas.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 43–46 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dd742cd1-1d43-52ae-9ad3-1f1d8ec45f9a', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Engenharia de Software', 'Médio', 'Na ausência de carrinho, um objeto compatível retorna quantidade e valor zero, sem exigir if em cada cliente. Qual padrão foi aplicado?', '["Null Object","Fixação da especialização na instanciação","Factory Method","Hook Method","Método final"]'::jsonb, 0, 'Null Object: objeto polimórfico que oferece comportamento adequado à ausência de um valor, evitando verificações de null espalhadas.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 43–46 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8b0a26c3-a9d7-5ce9-ba77-775248e935fa', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Método chamado pela lógica da superclasse cuja sobrescrita oferece um ponto de extensão.”?', '["Fixação da especialização na instanciação","Método protected","Hook Method","Extração das diferenças entre algoritmos","Método final"]'::jsonb, 2, 'Hook Method: método chamado pela lógica da superclasse cuja sobrescrita oferece um ponto de extensão.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 47–49 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fe65de1b-4798-5ffc-ac13-b68f231638b3', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Engenharia de Software', 'Médio', 'A superclasse conduz a operação e chama um método que a subclasse pode especializar. Como se chama esse ponto de extensão?', '["Extração das diferenças entre algoritmos","Método final","Factory Method","Hook Method","Método abstract"]'::jsonb, 3, 'Hook Method: método chamado pela lógica da superclasse cuja sobrescrita oferece um ponto de extensão.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 47–49 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a97ab497-a066-59da-8bf1-c891a8247047', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Método sem implementação que exige concretização em uma subclasse instanciável.”?', '["Fixação da especialização na instanciação","Método abstract","Factory Method","Null Object","Template Method"]'::jsonb, 1, 'Método abstract: método sem implementação que exige concretização em uma subclasse instanciável.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 49–50 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae4d0ea9-f325-58ca-a42f-dda333cbca7f', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Engenharia de Software', 'Médio', 'Uma operação da classe base não possui lógica padrão e toda subclasse concreta precisa implementá-la. Qual modificador expressa essa obrigação em Java?', '["Hook Method","Fixação da especialização na instanciação","Método abstract","Template Method","Null Object"]'::jsonb, 2, 'Método abstract: método sem implementação que exige concretização em uma subclasse instanciável.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 49–50 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('785a7ebc-26c3-596d-896a-4e5f5b341713', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Método cuja sobrescrita pelas subclasses é impedida.”?', '["Método final","Método protected","Extração das diferenças entre algoritmos","Null Object","Factory Method"]'::jsonb, 0, 'Método final: método cuja sobrescrita pelas subclasses é impedida.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 49–50 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('19ba59a6-4be4-5820-92ec-510de34adab2', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Engenharia de Software', 'Médio', 'A ordem de uma operação deve ficar protegida contra redefinição nas subclasses. Qual modificador aplicar ao método que controla essa ordem?', '["Hook Method","Template Method","Método final","Fixação da especialização na instanciação","Método abstract"]'::jsonb, 2, 'Método final: método cuja sobrescrita pelas subclasses é impedida.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 49–50 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7075e05a-8c4d-5089-be97-f58035959a17', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Membro acessível a subclasses e também às classes do mesmo pacote no modelo de acesso Java.”?', '["Método protected","Template Method","Hook Method","Null Object","Distinção entre gancho e template"]'::jsonb, 0, 'Método protected: membro acessível a subclasses e também às classes do mesmo pacote no modelo de acesso Java.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 49–50 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ca54410c-302c-5f09-8261-965f5751ac82', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Engenharia de Software', 'Médio', 'Um método de apoio deve estar disponível à especialização e às classes do pacote, sem integrar a API pública. Qual modificador se adequa a esse acesso?', '["Template Method","Método protected","Factory Method","Hook Method","Método final"]'::jsonb, 1, 'Método protected: membro acessível a subclasses e também às classes do mesmo pacote no modelo de acesso Java.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 49–50 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bbb5e232-7cc5-51ff-841a-bb92e89787b0', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Padrão que fixa o esqueleto de um algoritmo na superclasse e permite variar passos em subclasses.”?', '["Factory Method","Método final","Template Method","Null Object","Método protected"]'::jsonb, 2, 'Template Method: padrão que fixa o esqueleto de um algoritmo na superclasse e permite variar passos em subclasses.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 50–56 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ba9ae255-c034-5fb3-919a-0ca8b84c99b0', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Engenharia de Software', 'Médio', 'Importadores seguem sempre ler, interpretar e gravar, mas diferem na interpretação. Qual padrão conserva a sequência e especializa seus passos?', '["Método protected","Método abstract","Factory Method","Template Method","Null Object"]'::jsonb, 3, 'Template Method: padrão que fixa o esqueleto de um algoritmo na superclasse e permite variar passos em subclasses.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 50–56 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1dba26bc-4388-507b-95ad-34d59db9746b', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Separação entre um ponto de extensão isolado e a organização de um algoritmo em passos variáveis.”?', '["Método final","Null Object","Método protected","Extração das diferenças entre algoritmos","Distinção entre gancho e template"]'::jsonb, 4, 'Distinção entre gancho e template: separação entre um ponto de extensão isolado e a organização de um algoritmo em passos variáveis.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 52 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('be229bbd-bd38-5044-8075-563a12a936ff', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Engenharia de Software', 'Médio', 'Uma classe tem apenas um método sobrescrevível, sem definir um algoritmo em etapas. Que distinção impede concluir automaticamente que ela implementa Template Method?', '["Método abstract","Método final","Método protected","Factory Method","Distinção entre gancho e template"]'::jsonb, 4, 'Distinção entre gancho e template: separação entre um ponto de extensão isolado e a organização de um algoritmo em passos variáveis.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 52 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('327b0d83-0fbc-5eff-8514-1154dc24a62f', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Refatoração que isola trechos variáveis em métodos antes de elevar o fluxo comum à superclasse.”?', '["Factory Method","Método abstract","Método final","Null Object","Extração das diferenças entre algoritmos"]'::jsonb, 4, 'Extração das diferenças entre algoritmos: refatoração que isola trechos variáveis em métodos antes de elevar o fluxo comum à superclasse.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 57–60 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('552c9dbe-113d-5aaf-b2af-79a985513030', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Engenharia de Software', 'Médio', 'Duas rotinas quase iguais devem compartilhar uma estrutura base. Qual preparação localiza primeiro suas diferenças em métodos próprios?', '["Fixação da especialização na instanciação","Método protected","Hook Method","Extração das diferenças entre algoritmos","Null Object"]'::jsonb, 3, 'Extração das diferenças entre algoritmos: refatoração que isola trechos variáveis em métodos antes de elevar o fluxo comum à superclasse.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 57–60 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d52c089f-463c-5f7c-bad9-f84aa26f3420', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Padrão que delega a subclasses a escolha do objeto concreto criado por um método.”?', '["Fixação da especialização na instanciação","Factory Method","Template Method","Método final","Extração das diferenças entre algoritmos"]'::jsonb, 1, 'Factory Method: padrão que delega a subclasses a escolha do objeto concreto criado por um método.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 61–64 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('921bddaf-eeef-54b3-a9cb-756f40d8bfd2', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Engenharia de Software', 'Médio', 'Um serviço base precisa de um gerador de documento, mas cada especialização deve decidir qual implementação instanciar. Qual padrão atende a essa decisão?', '["Distinção entre gancho e template","Extração das diferenças entre algoritmos","Método protected","Factory Method","Fixação da especialização na instanciação"]'::jsonb, 3, 'Factory Method: padrão que delega a subclasses a escolha do objeto concreto criado por um método.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 61–64 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('56cfef04-369a-5ddc-b912-db8a9b8f0c97', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Engenharia de Software', 'Fácil', 'No estudo de “Reuso Através de Herança” em Guerra, qual conceito corresponde à descrição: “Limitação da variação por herança em que os passos disponíveis ficam ligados à classe concreta escolhida.”?', '["Fixação da especialização na instanciação","Método final","Extração das diferenças entre algoritmos","Null Object","Método protected"]'::jsonb, 0, 'Fixação da especialização na instanciação: limitação da variação por herança em que os passos disponíveis ficam ligados à classe concreta escolhida.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 55–56 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('429f496f-5fab-53e1-98bd-04bb2e98b522', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Engenharia de Software', 'Médio', 'Uma instância deve trocar um passo depois de criada, mas o passo foi definido por sobrescrita na sua classe. Qual limitação dessa estratégia dificulta a troca?', '["Método protected","Fixação da especialização na instanciação","Distinção entre gancho e template","Método abstract","Extração das diferenças entre algoritmos"]'::jsonb, 1, 'Fixação da especialização na instanciação: limitação da variação por herança em que os passos disponíveis ficam ligados à classe concreta escolhida.', 'GUERRA, Eduardo. Design Patterns com Java: projeto orientado a objetos guiado por padrões. Casa do Código, 2014 (ano indicado no arquivo fornecido). Capítulo 2: Reuso Através de Herança, páginas 55–56 do PDF fornecido. Questão original de estudo; não é questão oficial do CP-T.', false, false)
